import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ═══════════════════════════════════════════════════════════════
  // 1. BUILD STAGE & BACKDROP
  // ═══════════════════════════════════════════════════════════════
  const group = new THREE.Group();

  // Ribbon plane: 7.0w × 0.35h, centered at origin
  const ribbonGeo = new THREE.PlaneGeometry(7.0, 0.35);

  // ─────────────────────────────────────────────────────────────
  // Procedural material: surface #111117, hairlines, edge fades
  // ─────────────────────────────────────────────────────────────
  const uvNode = uv();

  // Top/bottom hairlines at y ≈ ±0.5, thickness 0.006 scene units
  // (texture space: 0.006/0.35 ≈ 0.017 of height)
  const hairlineThickness = 0.017;
  const topHairline = smoothstep(0.5 - hairlineThickness * 0.5, 0.5 + hairlineThickness * 0.5, uvNode.y);
  const bottomHairline = smoothstep(0.0 - hairlineThickness * 0.5, 0.0 + hairlineThickness * 0.5, uvNode.y);
  const hairlinePresence = mix(topHairline, 1.0, bottomHairline);

  // Edge fade masks: gradient ramp from #0b0b10ff at edges to transparent center
  // Left edge: x ∈ [0.0, 0.6/7.0 ≈ 0.086]
  // Right edge: x ∈ [1.0 - 0.086, 1.0]
  const fadeWidth = 0.6 / 7.0;
  const leftFade = smoothstep(0.0, fadeWidth, uvNode.x);
  const rightFade = smoothstep(1.0, 1.0 - fadeWidth, uvNode.x);
  const edgeFadeMask = mix(leftFade, 1.0, rightFade);

  // Combine: hairlines on surface, faded edges
  const surfaceColor = vec3(0.0667, 0.0667, 0.0706); // #111117
  const hairlineColor = vec3(0.137, 0.137, 0.169); // #23232b
  const ribbonColor = mix(hairlineColor, surfaceColor, hairlinePresence);

  const finalColor = mix(vec3(0.043, 0.043, 0.063), ribbonColor, edgeFadeMask); // #0b0b10 at edges

  const ribbonMaterial = new MeshBasicNodeMaterial({
    colorNode: mix(finalColor, vec3(1.0), 0.0),
  });
  ribbonMaterial.colorNode = finalColor;

  const ribbonMesh = new THREE.Mesh(ribbonGeo, ribbonMaterial);
  ribbonMesh.position.z = 0.0;
  group.add(ribbonMesh);

  // ═══════════════════════════════════════════════════════════════
  // 2. TICKER CONTENT & LAYOUT
  // ═══════════════════════════════════════════════════════════════
  const tickerItems = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18',
  ];

  const PAPER_COLOR = '#e8ecf2';
  const ACCENT_RED = '#ff2a38';
  const FONT_SIZE = 13;
  const LETTER_SPACING = 0.06;
  const GAP_AROUND_TICK = 0.5; // 2× base unit (base 0.25)
  const TICK_WIDTH = 0.02;
  const TICK_HEIGHT = 0.14;

  // Create ticker content strip
  const tickerStrip = new THREE.Group();

  let xOffset = 0.0;
  const contentParts = []; // for seamless loop calculation

  for (let i = 0; i < tickerItems.length; i++) {
    const text = tickerItems[i];

    // Render text
    const textMesh = ctx.fontAtlas.createText(text, {
      fontSize: FONT_SIZE,
      color: PAPER_COLOR,
      align: 'left',
      letterSpacingPx: LETTER_SPACING * 10, // rough scale
    });

    // Measure approximate width (heuristic: chars × font size × 0.5)
    const textWidth = (text.length * FONT_SIZE * 0.5) / 1000; // approx scene units

    // Position text on ribbon baseline
    textMesh.position.set(xOffset, 0.0, 0.02); // +0.02 translateZ for crisp edge
    tickerStrip.add(textMesh);
    contentParts.push({ x: xOffset, w: textWidth });

    xOffset += textWidth;

    // Add gap before tick (if not last item)
    if (i < tickerItems.length - 1) {
      xOffset += GAP_AROUND_TICK;

      // Accent tick mark (vertical bar, emissive red)
      const tickGeo = new THREE.PlaneGeometry(TICK_WIDTH, TICK_HEIGHT);
      const tickMat = new MeshBasicNodeMaterial({
        color: ACCENT_RED,
        emissive: ACCENT_RED,
        emissiveIntensity: 1.5,
      });
      const tickMesh = new THREE.Mesh(tickGeo, tickMat);
      tickMesh.position.set(xOffset, 0.0, 0.02);
      tickerStrip.add(tickMesh);

      xOffset += TICK_WIDTH + GAP_AROUND_TICK;
    }
  }

  const stripLength = xOffset;
  contentParts.push({ stripLength });

  // Duplicate strip for seamless loop
  const tickerStripDuplicate = tickerStrip.clone();
  tickerStripDuplicate.position.x = stripLength;
  tickerStrip.add(tickerStripDuplicate);

  group.add(tickerStrip);

  // ═══════════════════════════════════════════════════════════════
  // 3. FLY-THROUGH CINEMATIC PRIMITIVE
  // ═══════════════════════════════════════════════════════════════
  const speed = 0.4; // scene units per second, leftward
  const loopPeriod = stripLength / speed;

  const primResult = ctx.primitives['fly-through'](tickerStrip, {
    depthUnits: 0,
    speed: speed,
  });

  // Manual linear loop (fly-through may not loop; enforce linear leftward motion)
  const loopTimeline = gsap.timeline({ repeat: -1, yoyo: false });
  loopTimeline.fromTo(
    tickerStrip.position,
    { x: 0 },
    {
      x: -stripLength,
      duration: loopPeriod,
      ease: 'none', // linear
    },
    0
  );

  // ═══════════════════════════════════════════════════════════════
  // 4. CLEANUP
  // ═══════════════════════════════════════════════════════════════
  group.userData.cleanup = () => {
    if (primResult && primResult.cleanup) {
      primResult.cleanup();
    }
    if (loopTimeline) {
      loopTimeline.kill();
    }
    ribbonGeo.dispose();
    ribbonMaterial.dispose();
    tickerStrip.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });
  };

  return group;
}
